local cached = nil

local function GetData()
    if cached then return cached end
    cached = DATA
    return cached
end

local function GetByCategory(cat)
    local result = {}
    local data = GetData()
    for i = 1, #data do
        if data[i].category == cat then
            result[#result + 1] = data[i]
        end
    end
    return result
end

local function GetByID(id)
    local data = GetData()
    for i = 1, #data do
        if data[i].id == id then return data[i] end
    end
    return nil
end

_G.TJ_Words = {
    GetData = GetData,
    GetByCategory = GetByCategory,
    GetByID = GetByID,
}
